'use client'

import type { RowData } from '@tanstack/react-table'

import { DateRangeFilter } from './filters/date-range-filter'
import { MultiSelectFilter } from './filters/multi-select-filter'
import { NumberRangeFilter } from './filters/number-range-filter'
import { SelectFilter } from './filters/select-filter'
import { TextFilter } from './filters/text-filter'
import type { DataTableColumn } from './lib/types'

interface DataTableColumnFilterProps<TData extends RowData, TValue> {
  column: DataTableColumn<TData, TValue>
}

/** Renders the filter input configured in `meta.filter` for a column. */
export function DataTableColumnFilter<TData extends RowData, TValue>({
  column,
}: DataTableColumnFilterProps<TData, TValue>) {
  'use no memo'
  const config = column.columnDef.meta?.filter
  if (!config) return null

  // The value's shape is fixed by the variant, so each input narrows it.
  const value = column.getFilterValue() as never
  const onChange = (next: unknown) => column.setFilterValue(next)
  const props = { value, onChange }

  switch (config.variant) {
    case 'text':
      return (
        <TextFilter
          {...props}
          placeholder={config.placeholder}
          debounceMs={config.debounceMs}
        />
      )
    case 'select':
      return (
        <SelectFilter
          {...props}
          options={config.options}
          placeholder={config.placeholder}
        />
      )
    case 'multiSelect':
      return <MultiSelectFilter {...props} options={config.options} />
    case 'dateRange':
      return <DateRangeFilter {...props} />
    case 'numberRange':
      return <NumberRangeFilter {...props} />
  }

  return <config.component {...props} />
}

'use client'

import type { RowData } from '@tanstack/react-table'
import { ArrowDown, ArrowUp, ChevronsUpDown, EyeOff, ListFilter, X } from 'lucide-react'

import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import { Popover, PopoverContent, PopoverTrigger } from '@/components/ui/popover'

import { cn } from '@/lib/utils'

import { DataTableColumnFilter } from './data-table-column-filter'
import { useDataTableLocale } from './lib/locale'
import type { DataTableColumn } from './lib/types'

interface DataTableColumnHeaderProps<TData extends RowData, TValue> {
  column: DataTableColumn<TData, TValue>
  /** Defaults to `meta.label`, then the column id. */
  title?: string
  className?: string
}

export function DataTableColumnHeader<TData extends RowData, TValue>({
  column,
  title = column.columnDef.meta?.label ?? column.id,
  className,
}: DataTableColumnHeaderProps<TData, TValue>) {
  'use no memo'
  const locale = useDataTableLocale()
  const canSort = column.getCanSort()
  const canHide = column.getCanHide()
  const filter = column.columnDef.meta?.filter
  const canFilter = filter !== undefined && column.getCanFilter()

  if (!canSort && !canHide && !canFilter) {
    return <div className={className}>{title}</div>
  }

  const sorted = column.getIsSorted()
  const SortIcon =
    sorted === 'asc' ? ArrowUp : sorted === 'desc' ? ArrowDown : ChevronsUpDown

  return (
    <div className={cn('flex items-center gap-1', className)}>
      {canSort || canHide ? (
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <Button
              variant='ghost'
              size='sm'
              className='-ml-3 h-8 data-[state=open]:bg-accent'
            >
              {title}
              {canSort && <SortIcon className='text-muted-foreground' />}
            </Button>
          </DropdownMenuTrigger>
          <DropdownMenuContent align='start'>
            {canSort && (
              <>
                <DropdownMenuItem onSelect={() => column.toggleSorting(false)}>
                  <ArrowUp />
                  {locale.columnHeader.sortAscending}
                </DropdownMenuItem>
                <DropdownMenuItem onSelect={() => column.toggleSorting(true)}>
                  <ArrowDown />
                  {locale.columnHeader.sortDescending}
                </DropdownMenuItem>
                {sorted && (
                  <DropdownMenuItem onSelect={() => column.clearSorting()}>
                    <X />
                    {locale.columnHeader.clearSorting}
                  </DropdownMenuItem>
                )}
              </>
            )}
            {canSort && canHide && <DropdownMenuSeparator />}
            {canHide && (
              <DropdownMenuItem onSelect={() => column.toggleVisibility(false)}>
                <EyeOff />
                {locale.columnHeader.hideColumn}
              </DropdownMenuItem>
            )}
          </DropdownMenuContent>
        </DropdownMenu>
      ) : (
        <span>{title}</span>
      )}

      {canFilter && (
        <Popover>
          <PopoverTrigger asChild>
            <Button
              variant='ghost'
              size='icon-sm'
              aria-label={locale.columnHeader.filterColumn(title)}
              data-active={column.getIsFiltered() || undefined}
              className='text-muted-foreground data-active:bg-accent data-active:text-accent-foreground'
            >
              <ListFilter />
            </Button>
          </PopoverTrigger>
          <PopoverContent align='start' className='w-auto min-w-64 space-y-3'>
            {(filter.title || filter.description) && (
              <div className='space-y-1'>
                {filter.title && (
                  <h4 className='font-medium leading-none'>{filter.title}</h4>
                )}
                {filter.description && (
                  <p className='text-sm text-muted-foreground'>{filter.description}</p>
                )}
              </div>
            )}
            <DataTableColumnFilter column={column} />
            {column.getIsFiltered() && (
              <Button
                variant='outline'
                size='sm'
                className='w-full'
                onClick={() => column.setFilterValue(undefined)}
              >
                {locale.columnHeader.clearFilter}
              </Button>
            )}
          </PopoverContent>
        </Popover>
      )}
    </div>
  )
}

'use client'

import type { RowData, Table } from '@tanstack/react-table'

import { Checkbox } from '@/components/ui/checkbox'

import type { DataTableFeatures } from './lib/features'
import { useDataTableLocale } from './lib/locale'
import type { DataTableColumnDef, DataTableRow } from './lib/types'

export const SELECTION_COLUMN_ID = 'select'

function SelectAllCheckbox<TData extends RowData>({
  table,
}: {
  table: Table<DataTableFeatures, TData>
}) {
  'use no memo'
  const locale = useDataTableLocale()
  const allSelected = table.getIsAllPageRowsSelected()
  const someSelected = table.getIsSomePageRowsSelected()

  return (
    <Checkbox
      checked={allSelected || (someSelected && 'indeterminate')}
      onCheckedChange={(checked) => table.toggleAllPageRowsSelected(checked === true)}
      aria-label={locale.selection.selectAll}
    />
  )
}

function SelectRowCheckbox<TData extends RowData>({ row }: { row: DataTableRow<TData> }) {
  'use no memo'
  const locale = useDataTableLocale()

  return (
    <Checkbox
      checked={row.getIsSelected()}
      disabled={!row.getCanSelect()}
      onCheckedChange={(checked) => row.toggleSelected(checked === true)}
      aria-label={locale.selection.selectRow}
    />
  )
}

/**
 * A checkbox column for row selection. Put it first in your column list.
 * Which rows can be selected is controlled by the `enableRowSelection` option.
 */
export function createSelectionColumn<
  TData extends RowData,
>(): DataTableColumnDef<TData> {
  return {
    id: SELECTION_COLUMN_ID,
    header: ({ table }) => <SelectAllCheckbox table={table} />,
    cell: ({ row }) => <SelectRowCheckbox row={row} />,
    enableSorting: false,
    enableHiding: false,
    enableGlobalFilter: false,
    enableColumnFilter: false,
  }
}

'use client'

import type { RowData } from '@tanstack/react-table'
import { X } from 'lucide-react'
import type { ComponentProps } from 'react'

import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'

import { cn } from '@/lib/utils'

import { DataTableViewOptions } from './data-table-view-options'
import { useDataTableLocale } from './lib/locale'
import type { DataTableInstance } from './lib/types'

interface DataTableToolbarProps<TData extends RowData> extends ComponentProps<'div'> {
  table: DataTableInstance<TData>
  /** Shows the global search input. Defaults to `true`. */
  showSearch?: boolean
  /** Shows the column visibility menu. Defaults to `true`. */
  showViewOptions?: boolean
}

/**
 * Global search, a reset button for active filters, and the view options menu.
 * `children` render between the search input and the view options, which is
 * the place for extra filters or actions.
 */
export function DataTableToolbar<TData extends RowData>({
  table,
  showSearch = true,
  showViewOptions = true,
  className,
  children,
  ...props
}: DataTableToolbarProps<TData>) {
  'use no memo'
  const locale = useDataTableLocale()
  const globalFilter = (table.state.globalFilter as string | undefined) ?? ''
  const isFiltered = globalFilter !== '' || table.state.columnFilters.length > 0

  return (
    <div className={cn('flex flex-wrap items-center gap-2', className)} {...props}>
      {showSearch && (
        <Input
          type='search'
          value={globalFilter}
          placeholder={locale.toolbar.searchPlaceholder}
          aria-label={locale.toolbar.searchPlaceholder}
          onChange={(event) => table.setGlobalFilter(event.target.value)}
          className='h-8 w-40 lg:w-64'
        />
      )}
      {children}
      {isFiltered && (
        <Button
          variant='ghost'
          size='sm'
          className='h-8'
          onClick={() => {
            table.resetGlobalFilter(true)
            table.resetColumnFilters(true)
          }}
        >
          {locale.toolbar.reset}
          <X />
        </Button>
      )}
      {showViewOptions && (
        <div className='ml-auto'>
          <DataTableViewOptions table={table} />
        </div>
      )}
    </div>
  )
}

'use client'

import type { RowData } from '@tanstack/react-table'
import { Settings2 } from 'lucide-react'

import { Button } from '@/components/ui/button'
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'

import { useDataTableLocale } from './lib/locale'
import type { DataTableInstance } from './lib/types'

interface DataTableViewOptionsProps<TData extends RowData> {
  table: DataTableInstance<TData>
}

/** A menu to show and hide columns. Lists every hideable data column. */
export function DataTableViewOptions<TData extends RowData>({
  table,
}: DataTableViewOptionsProps<TData>) {
  'use no memo'
  const locale = useDataTableLocale()
  const columns = table
    .getAllLeafColumns()
    .filter((column) => column.accessorFn !== undefined && column.getCanHide())

  return (
    <DropdownMenu>
      <DropdownMenuTrigger asChild>
        <Button variant='outline' size='sm' className='h-8'>
          <Settings2 />
          {locale.viewOptions.view}
        </Button>
      </DropdownMenuTrigger>
      <DropdownMenuContent align='end' className='w-44'>
        <DropdownMenuLabel>{locale.viewOptions.toggleColumns}</DropdownMenuLabel>
        <DropdownMenuSeparator />
        {columns.map((column) => (
          <DropdownMenuCheckboxItem
            key={column.id}
            checked={column.getIsVisible()}
            onCheckedChange={(checked) => column.toggleVisibility(checked)}
            onSelect={(event) => event.preventDefault()}
          >
            {column.columnDef.meta?.label ?? column.id}
          </DropdownMenuCheckboxItem>
        ))}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

'use client'

import type { RowData } from '@tanstack/react-table'
import { Inbox } from 'lucide-react'
import type { ComponentProps, KeyboardEvent, MouseEvent, ReactNode } from 'react'

import { Empty, EmptyHeader, EmptyMedia, EmptyTitle } from '@/components/ui/empty'
import { Skeleton } from '@/components/ui/skeleton'
import { Spinner } from '@/components/ui/spinner'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'

import { cn } from '@/lib/utils'

import { useDataTableLocale } from './lib/locale'
import type { DataTableInstance, DataTableRow } from './lib/types'

// Clicks on these elements inside a row never trigger `onRowClick`.
const INTERACTIVE_SELECTOR =
  'a, button, input, select, textarea, label, [role="checkbox"], [role="menuitem"], [role="option"]'

export interface DataTableProps<TData extends RowData> extends ComponentProps<'div'> {
  table: DataTableInstance<TData>
  /** Renders skeleton rows instead of data, for the initial load. */
  isLoading?: boolean
  /** Overlays a spinner on the current rows, for background refetches. */
  isFetching?: boolean
  /** Replaces the default "no results" message. */
  emptyState?: ReactNode
  onRowClick?: (row: DataTableRow<TData>) => void
  skeletonRowCount?: number
}

export function DataTable<TData extends RowData>({
  table,
  isLoading = false,
  isFetching = false,
  emptyState,
  onRowClick,
  skeletonRowCount = 5,
  className,
  ...props
}: DataTableProps<TData>) {
  'use no memo'
  const locale = useDataTableLocale()
  const rows = table.getRowModel().rows
  const columnCount = table.getVisibleLeafColumns().length

  const handleRowClick = (event: MouseEvent<HTMLElement>, row: DataTableRow<TData>) => {
    if ((event.target as HTMLElement).closest(INTERACTIVE_SELECTOR)) return
    onRowClick?.(row)
  }

  const handleRowKeyDown = (
    event: KeyboardEvent<HTMLElement>,
    row: DataTableRow<TData>,
  ) => {
    if (event.target !== event.currentTarget) return
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault()
      onRowClick?.(row)
    }
  }

  return (
    <div
      className={cn('relative overflow-hidden rounded-md border', className)}
      aria-busy={isLoading || isFetching}
      {...props}
    >
      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <TableHead key={header.id} colSpan={header.colSpan}>
                  {header.isPlaceholder ? null : <table.FlexRender header={header} />}
                </TableHead>
              ))}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {isLoading ? (
            Array.from({ length: skeletonRowCount }, (_, rowIndex) => (
              <TableRow key={rowIndex} data-slot='data-table-skeleton-row'>
                {Array.from({ length: columnCount }, (_, cellIndex) => (
                  <TableCell key={cellIndex}>
                    <Skeleton className='h-4 w-full' />
                  </TableCell>
                ))}
              </TableRow>
            ))
          ) : rows.length > 0 ? (
            rows.map((row) => (
              <TableRow
                key={row.id}
                data-state={row.getIsSelected() ? 'selected' : undefined}
                className={cn(onRowClick && 'cursor-pointer')}
                tabIndex={onRowClick ? 0 : undefined}
                onClick={onRowClick ? (event) => handleRowClick(event, row) : undefined}
                onKeyDown={
                  onRowClick ? (event) => handleRowKeyDown(event, row) : undefined
                }
              >
                {row.getVisibleCells().map((cell) => (
                  <TableCell key={cell.id}>
                    <table.FlexRender cell={cell} />
                  </TableCell>
                ))}
              </TableRow>
            ))
          ) : (
            <TableRow>
              <TableCell colSpan={columnCount} className='h-24'>
                {emptyState ?? (
                  <Empty>
                    <EmptyHeader>
                      <EmptyMedia variant='icon'>
                        <Inbox />
                      </EmptyMedia>
                      <EmptyTitle>{locale.body.noResults}</EmptyTitle>
                    </EmptyHeader>
                  </Empty>
                )}
              </TableCell>
            </TableRow>
          )}
        </TableBody>
      </Table>
      {isFetching && !isLoading && (
        <div className='absolute inset-0 flex items-center justify-center bg-background/50'>
          <Spinner />
        </div>
      )}
    </div>
  )
}

'use client'

import { Calendar } from '@/components/ui/calendar'

import type { DateRangeFilterValue, FilterComponentProps } from '../lib/types'

export function DateRangeFilter({
  value,
  onChange,
}: FilterComponentProps<DateRangeFilterValue>) {
  return (
    <Calendar
      mode='range'
      selected={value?.from ? { from: value.from, to: value.to } : undefined}
      onSelect={(range) => onChange(range?.from || range?.to ? range : undefined)}
      defaultMonth={value?.from}
      captionLayout='dropdown'
      className='mx-auto p-0'
    />
  )
}

'use client'

import { Check } from 'lucide-react'

import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'

import { cn } from '@/lib/utils'

import { useDataTableLocale } from '../lib/locale'
import type {
  FilterComponentProps,
  FilterOption,
  MultiSelectFilterValue,
} from '../lib/types'

interface MultiSelectFilterProps extends FilterComponentProps<MultiSelectFilterValue> {
  options: FilterOption[]
}

export function MultiSelectFilter({
  value = [],
  onChange,
  options,
}: MultiSelectFilterProps) {
  const locale = useDataTableLocale()

  const toggle = (optionValue: string | number) => {
    const next = value.includes(optionValue)
      ? value.filter((selected) => selected !== optionValue)
      : [...value, optionValue]
    onChange(next.length > 0 ? next : undefined)
  }

  return (
    <Command className='rounded-md border'>
      <CommandInput placeholder={locale.filters.search} />
      <CommandList>
        <CommandEmpty>{locale.filters.noResults}</CommandEmpty>
        <CommandGroup>
          {options.map((option) => {
            const isSelected = value.includes(option.value)
            return (
              <CommandItem
                key={option.value}
                value={option.label}
                onSelect={() => toggle(option.value)}
                aria-selected={isSelected}
              >
                <div
                  className={cn(
                    'flex size-4 items-center justify-center rounded-sm border border-primary',
                    isSelected
                      ? 'bg-primary text-primary-foreground'
                      : 'opacity-50 [&_svg]:invisible',
                  )}
                >
                  <Check className='size-3 text-primary-foreground' />
                </div>
                {option.icon && <option.icon className='text-muted-foreground' />}
                {option.label}
              </CommandItem>
            )
          })}
        </CommandGroup>
      </CommandList>
    </Command>
  )
}

'use client'

import { Input } from '@/components/ui/input'

import { useDataTableLocale } from '../lib/locale'
import type { FilterComponentProps, NumberRangeFilterValue } from '../lib/types'

export function NumberRangeFilter({
  value = [],
  onChange,
}: FilterComponentProps<NumberRangeFilterValue>) {
  const locale = useDataTableLocale()
  const [min, max] = value

  const update = (next: NumberRangeFilterValue) =>
    onChange(next[0] === undefined && next[1] === undefined ? undefined : next)

  const parse = (input: string) => (input === '' ? undefined : Number(input))

  return (
    <div className='flex items-center gap-2'>
      <Input
        type='number'
        inputMode='decimal'
        placeholder={locale.filters.min}
        aria-label={locale.filters.min}
        value={min ?? ''}
        onChange={(event) => update([parse(event.target.value), max])}
        className='h-8'
      />
      <span className='text-muted-foreground'>–</span>
      <Input
        type='number'
        inputMode='decimal'
        placeholder={locale.filters.max}
        aria-label={locale.filters.max}
        value={max ?? ''}
        onChange={(event) => update([min, parse(event.target.value)])}
        className='h-8'
      />
    </div>
  )
}

'use client'

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'

import type { FilterComponentProps, FilterOption, SelectFilterValue } from '../lib/types'

interface SelectFilterProps extends FilterComponentProps<SelectFilterValue> {
  options: FilterOption[]
  placeholder?: string
}

export function SelectFilter({
  value,
  onChange,
  options,
  placeholder,
}: SelectFilterProps) {
  return (
    <Select
      value={value === undefined ? '' : String(value)}
      onValueChange={(next) =>
        onChange(options.find((option) => String(option.value) === next)?.value)
      }
    >
      <SelectTrigger size='sm' className='w-full'>
        <SelectValue placeholder={placeholder} />
      </SelectTrigger>
      <SelectContent>
        {options.map((option) => (
          <SelectItem key={option.value} value={String(option.value)}>
            {option.icon && <option.icon className='text-muted-foreground' />}
            {option.label}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  )
}

'use client'

import { useEffect, useRef, useState } from 'react'

import { Input } from '@/components/ui/input'

import type { FilterComponentProps, TextFilterValue } from '../lib/types'

interface TextFilterProps extends FilterComponentProps<TextFilterValue> {
  placeholder?: string
  debounceMs?: number
}

export function TextFilter({
  value,
  onChange,
  placeholder,
  debounceMs = 300,
}: TextFilterProps) {
  const [draft, setDraft] = useState(value ?? '')
  const [committed, setCommitted] = useState(value)

  // Reset the draft when the value changes from outside, e.g. "Clear filter".
  if (value !== committed) {
    setCommitted(value)
    setDraft(value ?? '')
  }
  const timeout = useRef<ReturnType<typeof setTimeout>>(undefined)

  useEffect(() => () => clearTimeout(timeout.current), [])

  return (
    <Input
      value={draft}
      placeholder={placeholder}
      onChange={(event) => {
        const next = event.target.value
        setDraft(next)
        clearTimeout(timeout.current)
        timeout.current = setTimeout(() => onChange(next || undefined), debounceMs)
      }}
      className='h-8'
    />
  )
}

import {
  constructFilterFn,
  filterFn_equals,
  filterFn_inNumberRange,
  filterFn_includesString,
} from '@tanstack/react-table'
import { endOfDay, startOfDay } from 'date-fns'

import type { DateRangeFilterValue, MultiSelectFilterValue } from './types'

function toTimestamp(value: unknown): number {
  if (value instanceof Date) return value.getTime()
  if (typeof value === 'number') return value
  if (typeof value === 'string' && value !== '') return new Date(value).getTime()
  return Number.NaN
}

/**
 * Matches rows whose value is one of the selected options. Array cell values
 * (e.g. tags) match when they contain at least one selected option.
 */
const multiSelect = constructFilterFn({
  filter: (dataValue: unknown, filterValue: MultiSelectFilterValue) =>
    Array.isArray(dataValue)
      ? dataValue.some((value) => filterValue.includes(value))
      : filterValue.includes(dataValue as string | number),
  autoRemove: (value: MultiSelectFilterValue | undefined) => !value?.length,
})

/**
 * Matches rows whose date falls inside the selected range. Both ends are
 * inclusive at day granularity, and a missing end leaves that side open.
 */
const dateRange = constructFilterFn({
  filter: (dataValue: number, [from, to]: [number, number]) =>
    !Number.isNaN(dataValue) && dataValue >= from && dataValue <= to,
  resolveFilterValue: (value: DateRangeFilterValue): [number, number] => [
    value.from ? startOfDay(value.from).getTime() : -Infinity,
    value.to ? endOfDay(value.to).getTime() : Infinity,
  ],
  resolveDataValue: toTimestamp,
  autoRemove: (value: DateRangeFilterValue | undefined) => !value?.from && !value?.to,
})

/**
 * Filter functions keyed by filter variant. `useDataTable` assigns the one
 * matching `meta.filter.variant` to any column that has no `filterFn` of its own.
 */
export const variantFilterFns = {
  text: filterFn_includesString,
  select: filterFn_equals,
  multiSelect,
  dateRange,
  numberRange: filterFn_inNumberRange,
}

'use client'

import { type ReactNode, createContext, useContext, useMemo } from 'react'

export interface DataTableLocale {
  body: {
    noResults: string
  }
  toolbar: {
    searchPlaceholder: string
    reset: string
  }
  viewOptions: {
    view: string
    toggleColumns: string
  }
  pagination: {
    rowsSelected: (selected: number, total: number) => string
    rowsPerPage: string
    pageOf: (page: number, pageCount: number) => string
    goToFirstPage: string
    goToPreviousPage: string
    goToNextPage: string
    goToLastPage: string
  }
  selection: {
    selectAll: string
    selectRow: string
  }
  columnHeader: {
    sortAscending: string
    sortDescending: string
    clearSorting: string
    hideColumn: string
    filterColumn: (title: string) => string
    clearFilter: string
  }
  filters: {
    search: string
    noResults: string
    min: string
    max: string
  }
}

export const defaultDataTableLocale: DataTableLocale = {
  body: {
    noResults: 'No results.',
  },
  toolbar: {
    searchPlaceholder: 'Search...',
    reset: 'Reset',
  },
  viewOptions: {
    view: 'View',
    toggleColumns: 'Toggle columns',
  },
  pagination: {
    rowsSelected: (selected, total) => `${selected} of ${total} row(s) selected.`,
